create table public.coach_conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Coach conversation',created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index coach_conversations_owner_time_idx on public.coach_conversations(user_id,updated_at desc);
create table public.coach_messages(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid not null references public.coach_conversations(id) on delete cascade,role text not null check(role in('user','assistant')),content text not null check(char_length(content) between 1 and 12000),domain text not null,safety_classification public.safety_classification not null default 'normal',evidence_ids uuid[] not null default '{}',model text,created_at timestamptz not null default now());create index coach_messages_conversation_time_idx on public.coach_messages(conversation_id,created_at);create index coach_messages_owner_time_idx on public.coach_messages(user_id,created_at desc);
create table public.evidence_records(id uuid primary key default gen_random_uuid(),title text not null,organization text not null,publication_type text not null,publication_date date,reviewed_at date not null,topic_tags text[] not null,claim_summary text not null,evidence_tier smallint not null check(evidence_tier between 1 and 4),applicable_context text not null,limitations text not null,source_locator text not null unique,review_status text not null check(review_status in('draft','reviewed','retired')),reviewer text not null,methodology_version text not null,created_at timestamptz not null default now());create index evidence_records_topics_idx on public.evidence_records using gin(topic_tags);
create table public.coach_memory_candidates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,source_message_id uuid not null references public.coach_messages(id) on delete cascade,candidate_type text not null,explicit_value jsonb,inferred_value jsonb,provenance text not null check(provenance in('explicit','inferred')),confirmation_status text not null default 'pending' check(confirmation_status in('pending','confirmed','edited','removed')),persistent boolean not null default false,created_at timestamptz not null default now(),decided_at timestamptz);create index coach_memory_candidates_owner_idx on public.coach_memory_candidates(user_id,created_at desc);create index coach_memory_candidates_message_idx on public.coach_memory_candidates(source_message_id);
create table public.equipment_recognition_candidates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid references public.coach_conversations(id) on delete cascade,candidates jsonb not null,confirmed_inventory text[],scope text not null default 'session_only' check(scope in('session_only','date_range','week')),confirmation_status text not null default 'pending' check(confirmation_status in('pending','confirmed','cancelled')),model text not null,created_at timestamptz not null default now(),confirmed_at timestamptz);create index equipment_recognition_owner_idx on public.equipment_recognition_candidates(user_id,created_at desc);create index equipment_recognition_conversation_idx on public.equipment_recognition_candidates(conversation_id);
create table public.coach_answer_feedback(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,message_id uuid not null references public.coach_messages(id) on delete cascade,helpful boolean not null,reason_code text check(reason_code in('incorrect','unclear','too_long','not_personalized','unsafe','other')),created_at timestamptz not null default now(),unique(user_id,message_id));create index coach_feedback_message_idx on public.coach_answer_feedback(message_id);
insert into public.evidence_records(title,organization,publication_type,publication_date,reviewed_at,topic_tags,claim_summary,evidence_tier,applicable_context,limitations,source_locator,review_status,reviewer,methodology_version) values
('Progression Models in Resistance Training for Healthy Adults','American College of Sports Medicine','position stand','2009-03-01','2026-08-17','{training,progression,strength}','Progressive resistance training should manipulate load, volume, frequency, rest, and velocity according to training status and goals.',1,'Healthy adults performing resistance training.','Requires individualization; does not replace clinical guidance.','doi:10.1249/MSS.0b013e3181915670','reviewed','STHENO methodology review','2026.08'),
('International Society of Sports Nutrition Position Stand: protein and exercise','International Society of Sports Nutrition','position stand','2017-06-20','2026-08-17','{nutrition,protein,muscle_gain}','Adequate daily protein distributed across meals supports training adaptation; needs vary by body size, energy intake, and training.',1,'Healthy exercising adults.','Special populations and medical conditions need individualized guidance.','doi:10.1186/s12970-017-0177-8','reviewed','STHENO methodology review','2026.08'),
('Common Questions and Misconceptions About Creatine Supplementation','International Society of Sports Nutrition','peer-reviewed review','2021-02-08','2026-08-17','{supplements,creatine,strength}','Creatine monohydrate is the most studied form and can support repeated high-intensity performance and training adaptation.',1,'Healthy adults; sport and resistance-training contexts.','Contraindications and individual clinical context still matter.','doi:10.1186/s12970-021-00412-w','reviewed','STHENO methodology review','2026.08'),
('WHO Guidelines on Physical Activity and Sedentary Behaviour','World Health Organization','guideline','2020-11-25','2026-08-17','{cardio,activity,health}','Adults benefit from regular aerobic and muscle-strengthening activity; some activity is better than none.',1,'General adult population with separate guidance for specific populations.','Fitness programming requires individual capacity and constraints.','https://www.who.int/publications/i/item/9789240015128','reviewed','STHENO methodology review','2026.08'),
('Recommended Amount of Sleep for a Healthy Adult','American Academy of Sleep Medicine and Sleep Research Society','consensus recommendation','2015-06-01','2026-08-17','{sleep,recovery}','Adults should generally sleep seven or more hours per night regularly to support health.',1,'Healthy adults aged 18–60.','Sleep need and disorders require individualized clinical assessment.','doi:10.5664/jcsm.4758','reviewed','STHENO methodology review','2026.08') on conflict(source_locator) do update set reviewed_at=excluded.reviewed_at,claim_summary=excluded.claim_summary,methodology_version=excluded.methodology_version;
do $$declare t text;begin foreach t in array array['coach_conversations','coach_messages','coach_memory_candidates','equipment_recognition_candidates','coach_answer_feedback'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using((select auth.uid())=user_id)',t||'_select_own',t);execute format('create policy %I on public.%I for insert to authenticated with check((select auth.uid())=user_id)',t||'_insert_own',t);execute format('create policy %I on public.%I for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id)',t||'_update_own',t);execute format('grant select,insert,update on public.%I to authenticated',t);end loop;end$$;alter table public.evidence_records enable row level security;create policy evidence_records_read_reviewed on public.evidence_records for select to authenticated using(review_status='reviewed');grant select on public.evidence_records to authenticated;
